const test=require('node:test'),assert=require('node:assert/strict');
const t=require('../terrain-presets.js'),e=require('../procedural-engine.js');
test('five distinct terrain recipes round-trip exactly and stay in the current biome',()=>{assert.equal(t.presets.length,5);const fields=new Set();for(const p of t.presets){const r=t.recipe(p.id,41),a=t.generate(r),b=t.generate(JSON.parse(JSON.stringify(r)));assert.deepEqual(a,b);assert.equal(a.biome,'meadow-woodland-brook');assert.equal(t.match(a.config).id,p.id);fields.add(JSON.stringify(a.terrain.grid.heights));}assert.equal(fields.size,5);});
test('tile contract preserves metre heights and supplies six real edge profiles',()=>{for(const p of t.presets){const w=t.generate(t.recipe(p.id,41)),v=t.provider(w);assert.equal(v.footprint.radiusMetres,50);assert.equal(v.edges.length,6);assert.equal(v.coordinates.axes.y,'up');const n=(v.grid.rows-1)/2;assert(Math.abs(v.grid.values[n][n].heightMetres-e.sample(w,90,90))<1e-5);for(const edge of v.edges)for(const s of edge.samples){assert.equal(s.status,'sampled');assert(Number.isFinite(s.heightMetres));assert(s.slopeRiseOverRun>=0);assert.equal(s.buildableCandidate,s.bankDistanceMetres>=5&&s.slopeRiseOverRun<=.12);}for(const region of v.suitability.regions)for(const i of region.sampleIndices)assert(v.grid.values[Math.floor(i/v.grid.cols)][i%v.grid.cols].buildableCandidate);assert.equal(v.neighborCompatibility.status,'unknown');assert.equal(v.capabilities.snowIce,'unsupported');assert.equal(v.capabilities.floodRisk,'unknown');}});
test('exports reject unsupported versions and can restore custom settings',()=>{assert.throws(()=>t.recipe('unknown'));const r=t.recipe('meadow-clearing');assert.throws(()=>t.generate({...r,schemaVersion:'99'}));const custom={...r,prefabId:'custom',parameters:{...r.parameters,hillHeight:3}};assert.equal(t.generate(custom).config.hillHeight,3);assert.throws(()=>t.provider(t.generate(r),{radiusMetres:500}));});
test('open meadow preset leaves room for connected ranch growth',()=>{for(const seed of [41,81,127]){const g=e.grow(t.generate(t.recipe('meadow-clearing',seed)));assert(g.checks.dry&&g.checks.nonoverlap&&g.checks.connected);}});
test('new zones expose actual surfaces and exclude water and wet ground from candidate pads',()=>{const wanted={wetland:['wet-ground','freshwater'],'rocky-foothills':['rock'],'coast-estuary':['sand','saltwater','brackish-water']};for(const z of t.zones){const w=t.generate(t.recipe(z.preset,41,{biome:z.id})),p=t.provider(w);assert.equal(w.biome,z.id);assert(w.terrain.grid.heights.flat().every(Number.isFinite));for(const surface of wanted[z.id]||[])assert(w.terrain.surfaceGrid.values.flat().includes(surface),z.id+': '+surface);for(const row of p.grid.values)for(const s of row)if(s&&['water','wet-ground'].includes(s.surface)){assert(!s.buildableCandidate);assert(s.protected);}assert.equal(p.capabilities.soilBearing,'unknown');assert.equal(p.capabilities.hydrology,'unsupported');}});
